  const v = document.getElementById('inp').value;
  if (!v) { document.getElementById('out').textContent = '—'; return; }
  const n = parseFloat(v);
  if (isNaN(n)) { document.getElementById('out').textContent = 'Invalid'; return; }
  document.getElementById('out').textContent = 'Result: ' + n;
}

